#include <Servo.h>

Servo servo1;  // первый сервопривод
Servo servo2;  // второй сервопривод

// Пины подключения сигнальных проводов сервоприводов
const int PIN_SERVO1 = 9;
const int PIN_SERVO2 = 10;

void setup() {
  servo1.attach(PIN_SERVO1);
  servo2.attach(PIN_SERVO2);

  // Начальное положение
  servo1.write(90);
  servo2.write(90);
  delay(500);

  // Инициализация генератора случайных чисел
  randomSeed(analogRead(A0));
}

void loop() {
  // Случайный угол для каждого сервопривода (0–180°)
  int angle1 = random(0, 181);
  int angle2 = random(0, 181);

  servo1.write(angle1);
  servo2.write(angle2);

  // Случайная пауза между движениями (300–1500 мс)
  int pauseTime = random(300, 1500);
  delay(pauseTime);
}
